def _parse_attrs(options: Dict[str, Any]) ->Dict[str, Any]:
    attrs = {}
    if 'alt' in options:
        attrs['alt'] = options['alt']
    if 'target' in options:
        attrs['target'] = options['target']

    for key in ['width', 'height']:
        if key in options:
            value = options[key]
            match = _num_re.match(value)
            if match:
                attrs[key] = value

    if 'align' in options:
        align = options['align']
        if align in _allowed_aligns:
            attrs['align'] = align

    return attrs

def render_block_image(self: 'HTMLRenderer', src: str, alt: Optional[str]=
    None, width: Optional[str]=None, height: Optional[str]=None, **attrs: Any
    ) ->str:
    html = '<img src="' + escape_url(src) + '"'
    if alt:
        html += ' alt="' + escape_text(alt) + '"'
    if width:
        html += ' width="' + escape_text(width) + '"'
    if height:
        html += ' height="' + escape_text(height) + '"'
    if 'align' in attrs:
        html += ' align="' + escape_text(attrs['align']) + '"'
    if 'target' in attrs:
        html += ' usemap="' + escape_text(attrs['target']) + '"'
    return html + ' />\n'

def parse(self, block: 'BlockParser', m: Match[str], state: 'BlockState'
    ) ->Dict[str, Any]:
    options = dict(self.parse_options(m))
    attrs = _parse_attrs(options)
    attrs['src'] = self.parse_title(m)
    return {'type': 'block_image', 'attrs': attrs}

def __call__(self, directive: 'BaseDirective', md: 'Markdown') ->None:
    directive.register(self.NAME, self.parse)
    assert md.renderer is not None
    if md.renderer.NAME == 'html':
        md.renderer.register('block_image', render_block_image)
